import{ct as e,n as t,st as n,wt as r}from"./chunks/framework.eUj94whv.js";var i=JSON.parse(`{"title":"LLMs.txt","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llms.md","filePath":"ai/llms.md","lastUpdated":1791958925000}`),a={name:`ai/llms.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="llms-txt" tabindex="-1">LLMs.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to “LLMs.txt”">​</a></h1><p>文档站在构建时产出一组给大语言模型读的机读资产，内容与站点正文同源。AI 工具读取它们即可了解 XiHan.UI 的组件、API 与用法。</p><h2 id="可用资源" tabindex="-1">可用资源 <a class="header-anchor" href="#可用资源" aria-label="Permalink to “可用资源”">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://ui.docs.xihanfun.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a></td><td>索引：全部页面的标题、一句话摘要与地址，以及下列资产的入口</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a></td><td>全站正文，组件示例已内联为 Vue 与 Web Components 源码</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-components.txt" target="_blank" rel="noreferrer">llms-components.txt</a></td><td>组件参考：部件、Props、事件、状态、键盘、数据属性、CSS 变量与示例</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-guide.txt" target="_blank" rel="noreferrer">llms-guide.txt</a></td><td>核心概念、适配器与服务运行时</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/llms-tokens.txt" target="_blank" rel="noreferrer">llms-tokens.txt</a></td><td>设计令牌全表：名字、类型、缺省取值与改写档</td></tr><tr><td><a href="https://ui.docs.xihanfun.com/design.md" target="_blank" rel="noreferrer">design.md</a></td><td>缺省主题的设计语言，见 <a href="./design-md">design.md</a></td></tr><tr><td><a href="https://ui.docs.xihanfun.com/ai/SKILL.md" target="_blank" rel="noreferrer">ai/SKILL.md</a></td><td>给 AI 编程工具的使用规范，见 <a href="./agents">For Agents</a></td></tr></tbody></table><p><strong>单页 Markdown</strong>：任何一页的站点地址后加 <code>.md</code> 即可取到这一页的 Markdown，如 <a href="https://ui.docs.xihanfun.com/components/select.md" target="_blank" rel="noreferrer">components/select.md</a>、<a href="https://ui.docs.xihanfun.com/guide/theme.md" target="_blank" rel="noreferrer">guide/theme.md</a>。每页正文上方的「取本页 Markdown」也指向它。</p><p><code>llms-full.txt</code> 体积较大，多数场景读 <code>llms.txt</code> 索引后按需取单页，或只取 <code>llms-components.txt</code> 中用到的组件。</p><h2 id="在-ai-工具中使用" tabindex="-1">在 AI 工具中使用 <a class="header-anchor" href="#在-ai-工具中使用" aria-label="Permalink to “在 AI 工具中使用”">​</a></h2><p>所有工具都可以用同一段提示词：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阅读 https://ui.docs.xihanfun.com/llms.txt 了解 XiHan.UI，写 XiHan.UI 代码时按需读取其中列出的页面（站点地址后加 .md 取 Markdown），以文档为准，不要凭记忆写组件 API。</span></span></code></pre></div><table tabindex="0"><thead><tr><th>工具</th><th>做法</th></tr></thead><tbody><tr><td>Claude Code</td><td>写进项目的 <code>CLAUDE.md</code>，或用 <code>/memory</code> 记下</td></tr><tr><td>Cursor</td><td>在对话中用 <code>@Docs</code> 添加 <code>https://ui.docs.xihanfun.com/llms.txt</code>，或写进 <code>.cursor/rules</code></td></tr><tr><td>Codex</td><td>写进项目的 <code>AGENTS.md</code></td></tr><tr><td>GitHub Copilot</td><td>写进 <code>.github/copilot-instructions.md</code></td></tr><tr><td>Windsurf</td><td>写进 <code>.windsurf/rules</code></td></tr></tbody></table><p>能运行命令或接入 MCP 的工具，优先用 <a href="./cli">CLI</a> 或 <a href="./mcp">MCP Server</a>：数据离线且与项目版本一致，而文档站上的资产对应最新发布的版本。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./agents">For Agents</a> · <a href="./mcp">MCP Server</a> · <a href="./design-md">design.md</a></li></ul>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};